import { Box } from '@mui/material'
import React, { memo, useMemo } from 'react'

import IconProps from '@/assets/IconProps'
import { colorTokens } from '@/theme/colorTokens'
import type palette from '@/theme/palette'

type Shade = keyof (typeof palette)[keyof typeof palette]
type PaletteColor = keyof typeof palette

// Figma has no circular tile; the palette-name props map onto the DS primitive
// variables, where each palette's `main` is its 500 shade.
const PRIMITIVE_FAMILY: Record<PaletteColor, string> = {
  primary: 'cyans',
  secondary: 'greens',
  grey: 'neutrals',
  warning: 'yellows',
  error: 'red',
}

const primitiveColor = (color: PaletteColor, shade: Shade) =>
  `var(--rc-color-${PRIMITIVE_FAMILY[color]}-${shade === 'main' ? '500' : shade})`

interface Props {
  bgShade?: Shade | 'white'
  color?: keyof typeof palette
  Icon: React.JSXElementConstructor<IconProps>
  iconShade?: Shade | 'white'
  size?: 'tiny' | 'small' | 'medium' | 'mediumLarge' | 'large'
}
function IconWithCircularBackground(props: Props) {
  const { Icon } = props

  const bgShade: Props['bgShade'] = props?.bgShade ?? '50'
  const iconShade: Props['iconShade'] = props?.iconShade ?? '600'

  const color = props?.color ?? 'primary'
  const size = props?.size ?? 'medium'

  const sizes = useMemo<[string, string]>(() => {
    switch (size) {
      case 'tiny':
        return ['1.5rem', '1rem']
      case 'small':
        return ['2rem', '1rem']
      case 'medium':
        return ['2.5rem', '1.5rem']
      case 'mediumLarge':
        return ['3.5rem', '2rem']
      case 'large':
        return ['4.25rem', '2.25rem']
      default:
        return ['2.5rem', '1.5rem']
    }
  }, [size])

  return (
    <Box
      className='IconWithCircularBackground-root'
      sx={{
        alignItems: 'center',
        backgroundColor:
          bgShade === 'white'
            ? colorTokens['surface-base']
            : primitiveColor(color, bgShade),
        borderRadius: '50%',
        display: 'flex',
        justifyContent: 'center',
        height: sizes[0],
        width: sizes[0],
        aspectRatio: '1 / 1',

        svg: {
          height: sizes[1],
          width: sizes[1],
        },
        'svg path': {
          fill:
            iconShade === 'white'
              ? colorTokens['text-inverse']
              : primitiveColor(color, iconShade),
        },
      }}
    >
      <Icon />
    </Box>
  )
}

export default memo(IconWithCircularBackground)
